import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const C=JSON.parse('{"title":"ChatGPT 套餐与 Codex 访问","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/codex/chatgpt-plus.md","filePath":"zh/products/ai-coding/codex/chatgpt-plus.md","lastUpdated":1787107158000}'),d={name:"zh/products/ai-coding/codex/chatgpt-plus.md"};function s(l,t,i,n,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="chatgpt-套餐与-codex-访问" tabindex="-1">ChatGPT 套餐与 Codex 访问 <a class="header-anchor" href="#chatgpt-套餐与-codex-访问" aria-label="Permalink to &quot;ChatGPT 套餐与 Codex 访问&quot;">​</a></h1><blockquote><p>Codex 访问权如何挂在 ChatGPT 套餐上、套餐之间真正差在哪、数字该去哪查。</p><p><strong>本页故意不写价格和配额数字。</strong> 那些数字会变，教程里留一个过期数字比没有更糟。唯一权威来源是<a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">官方定价页</a>。</p></blockquote><h2 id="codex-包含在-chatgpt-套餐里" tabindex="-1">Codex 包含在 ChatGPT 套餐里 <a class="header-anchor" href="#codex-包含在-chatgpt-套餐里" aria-label="Permalink to &quot;Codex 包含在 ChatGPT 套餐里&quot;">​</a></h2><p>官方产品落地页原文：</p><blockquote><p>ChatGPT Plus, Pro, Business, Edu, and Enterprise plans include Codex.</p></blockquote><p>对 CLI 来说，关键事实是：<strong>不用单独买 Codex，日常使用也不用先配 API Key。</strong> 用 ChatGPT 账号登录即可。</p><p><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">定价页</a>另外列出 <strong>Free</strong> 和 <strong>Go</strong> 也包含部分 Codex 能力。明确写出「网页 / CLI / IDE 扩展 / iOS」的是 Plus 卡片。入口和额度按套餐不同——去定价页看，不要信教程里的表。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 已保存凭证时退出码为 0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 本地诊断报告</span></span></code></pre></div><p>官方 CLI 参考里<strong>没有</strong> <code>codex status</code> 子命令。当前会话的账号、模型、配置，用 TUI 里的 <code>/status</code>。</p><h2 id="套餐差在哪" tabindex="-1">套餐差在哪 <a class="header-anchor" href="#套餐差在哪" aria-label="Permalink to &quot;套餐差在哪&quot;">​</a></h2><p>与其复制一张下个月就会过期的表，不如知道读定价页时该盯哪些维度：</p><table tabindex="0"><thead><tr><th>会变的东西</th><th>为什么在乎</th></tr></thead><tbody><tr><td>触顶之前的包含用量</td><td>重度 Agent 工作一天能撑多久</td></tr><tr><td>模型访问</td><td>最新或最快的模型你能不能用</td></tr><tr><td>Cloud 执行容量</td><td>能往 <code>codex cloud</code> 丢多少</td></tr><tr><td>管理与治理</td><td>能不能用 <code>requirements.toml</code> 在团队里强制策略</td></tr><tr><td>席位管理</td><td>按人还是按组织</td></tr></tbody></table><p>两件有出处、值得记住的事：</p><ul><li><strong>ChatGPT Pro</strong> 包含研究预览模型 <code>GPT-5.3-Codex-Spark</code>。</li><li><strong>Business / Edu / Enterprise</strong> 才是托管配置真正有意义的套餐——管理员能钉住什么，见 <a href="./codex-glossary.html#requirementstoml-managed-policy">requirements.toml</a>。</li></ul><p>任何数字都去 <a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">learn.chatgpt.com/docs/pricing</a> 查。</p><h2 id="看自己的消耗" tabindex="-1">看自己的消耗 <a class="header-anchor" href="#看自己的消耗" aria-label="Permalink to &quot;看自己的消耗&quot;">​</a></h2><p>会话内查询比事后翻仪表盘有用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/usage              # 当前会话</span></span>
<span class="line"><span>/usage daily</span></span>
<span class="line"><span>/usage weekly</span></span>
<span class="line"><span>/usage cumulative</span></span></code></pre></div><p><code>/status</code> 显示当前会话的账号、模型、配置。</p><p>两个习惯能让消耗可预期：</p><p><strong>推理强度匹配任务。</strong> <code>model_reasoning_effort</code> 从 <code>minimal</code> 到 <code>xhigh</code>。一行重命名开 high 是浪费；隐蔽的并发 bug 开 low 是假节约。</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_reasoning_effort = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;medium&quot;</span></span></code></pre></div><p><strong>别扛着死上下文。</strong> 跑偏的长会话会把预算花在重读已经无关的历史。不相关任务之间 <code>/clear</code>，是最便宜的优化。</p><h2 id="api-计费是另一条线" tabindex="-1">API 计费是另一条线 <a class="header-anchor" href="#api-计费是另一条线" aria-label="Permalink to &quot;API 计费是另一条线&quot;">​</a></h2><p>下面两件事走 OpenAI API 账单，而不是 ChatGPT 套餐，而且都是<strong>选择加入</strong>：</p><ul><li><strong>自定义 model provider。</strong> <code>model_providers</code> 指到你自己的端点时，按那个端点计费。</li><li><strong>大批量图像生成。</strong> 图像生成默认吃包含额度，文档写消耗大约是文本的 3 到 5 倍。设置 <code>OPENAI_API_KEY</code> 会把大批量切到 API 定价。</li></ul><p>用 <code>codex login</code> 的日常 CLI 使用，这两条都不适用。从没设过 <code>OPENAI_API_KEY</code>、没碰过 <code>model_providers</code>，用量就在 ChatGPT 套餐上。</p><blockquote><p>当前配置参考里没有 <code>api_key</code> 这个键。认证是 <code>codex login</code>，或在 provider 条目里用 <code>env_key</code> 指向环境变量。 更老的教程有时会在 <code>config.toml</code> 里写 <code>api_key</code>；现行官方参考里没有这一项。</p></blockquote><h2 id="企业与团队部署" tabindex="-1">企业与团队部署 <a class="header-anchor" href="#企业与团队部署" aria-label="Permalink to &quot;企业与团队部署&quot;">​</a></h2><p>团队落地时，真正相关的不是套餐页，而是托管策略层：</p><table tabindex="0"><thead><tr><th>关注点</th><th>机制</th></tr></thead><tbody><tr><td>限制可选审批策略</td><td><code>requirements.toml</code> 的 <code>allowed_approval_policies</code></td></tr><tr><td>限制沙箱模式</td><td><code>allowed_sandbox_modes</code></td></tr><tr><td>限制网页搜索</td><td><code>allowed_web_search_modes</code>（<code>disabled</code> 始终允许）</td></tr><tr><td>MCP 服务器白名单</td><td>带 <code>identity</code> 块的 <code>mcp_servers</code> 条目</td></tr><tr><td>钉死 feature flag</td><td><code>requirements.toml</code> 的 <code>[features]</code></td></tr><tr><td>数据驻留</td><td><code>enforce_residency</code></td></tr></tbody></table><p>托管 permission-profile 白名单需要 <strong>Codex 0.138.0 或更高</strong>。0.137.0 及更早的客户端会静默忽略 <code>allowed_permission_profiles</code> 和托管 <code>default_permissions</code>——没核对客户端版本的「强制策略」等于没强制。</p><p>完整 <code>requirements.toml</code> 表面见 <a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Configuration Reference</a>。</p><h2 id="chatgpt-chat-对话智能" tabindex="-1">ChatGPT Chat（对话智能） <a class="header-anchor" href="#chatgpt-chat-对话智能" aria-label="Permalink to &quot;ChatGPT Chat（对话智能） {#chatgpt-chat-对话智能}&quot;">​</a></h2><p>对位 Claude.ai 的是 <strong>Chat</strong>，不是另装一个产品。官方把同一应用切成 Chat / Work / Codex（<a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a>）。</p><table tabindex="0"><thead><tr><th>选</th><th>何时用</th><th>本教程落点</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>问答、头脑风暴、短草稿、把设计谈清楚</td><td>本页</td></tr><tr><td><strong>Work</strong></td><td>要一份能打开检查的成品</td><td><a href="./chatgpt-work.html">ChatGPT Work</a></td></tr><tr><td><strong>Codex</strong></td><td>仓库、diff、测试、PR</td><td><a href="./codex-ai.html">产品线</a> · <a href="./codex-cli.html">CLI</a></td></tr></tbody></table><p>Chat 侧前端工程师会反复碰到的能力：</p><ul><li><strong>Projects</strong>：同一主题下的会话、文件、指令。</li><li><strong>Voice</strong>：桌面和 iOS；可对着上传文件和 Project 说话。</li><li><strong>Library</strong>：已保存文件再次引用，不必重传。</li><li><strong>网页 / 桌面 / 手机</strong>：同一账号。2026-07-09 起独立 Codex 应用并入 <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT 桌面应用</a>；每个套餐（含 Free）都能进 Chat、Work、Codex，额度仍按定价页。</li></ul><p>Chat 里的 GPT-5.6 Sol 滑块只影响 Chat，<strong>不</strong>改变 Work 或 Codex 的模型行为。</p><h2 id="chatgpt-和-codex-怎么配合" tabindex="-1">ChatGPT 和 Codex 怎么配合 <a class="header-anchor" href="#chatgpt-和-codex-怎么配合" aria-label="Permalink to &quot;ChatGPT 和 Codex 怎么配合&quot;">​</a></h2><p>它们强项不同，配对是真的有用：</p><table tabindex="0"><thead><tr><th>任务</th><th>更合适的地方</th></tr></thead><tbody><tr><td>代码还不存在时把思路谈清楚</td><td>Chat</td></tr><tr><td>比库、比架构</td><td>Chat</td></tr><tr><td>要八页 PPT / 对比表 / 定期议程</td><td><a href="./chatgpt-work.html">Work</a></td></tr><tr><td>在真实仓库里读改文件</td><td>Codex</td></tr><tr><td>跑测试并迭代到绿</td><td>Codex</td></tr><tr><td>给同事解释一份 diff</td><td>Chat</td></tr><tr><td>CI 里自动化一项任务</td><td>Codex（<code>codex exec</code>）</td></tr></tbody></table><p>可用工作流：在 Chat 里把设计谈定，写成 <code>AGENTS.md</code> 条目或任务说明，再把实现交给 Codex 并写上验收命令。设计对话和实现会话的上下文需求完全不同，拆开两边都更好。</p><h2 id="atlas-官方已下线-不要当现行产品写" tabindex="-1">Atlas：官方已下线，不要当现行产品写 <a class="header-anchor" href="#atlas-官方已下线-不要当现行产品写" aria-label="Permalink to &quot;Atlas：官方已下线，不要当现行产品写&quot;">​</a></h2><p>独立浏览器 <strong>ChatGPT Atlas</strong> 不是「桌面 superapp 传闻」，官方已经收口：</p><ul><li><a href="https://help.openai.com/en/articles/20001371-evolving-atlas-into-chatgpt-for-browser-based-agentic-work" target="_blank" rel="noreferrer">Evolving Atlas into ChatGPT</a>：把基于浏览器的代理能力迁进 ChatGPT 和 Codex；<strong>Atlas 计划于 2026-08-09 停止工作</strong>。</li><li><a href="https://openai.com/index/chatgpt-for-your-most-ambitious-work/" target="_blank" rel="noreferrer">ChatGPT is now a partner for your most ambitious work</a>（2026-07-09）：Codex 应用并入新的 ChatGPT 桌面应用；「We&#39;ll begin sunsetting the standalone Atlas browser」。</li><li><a href="https://help.openai.com/en/articles/6825453-chatgpt-release-notes" target="_blank" rel="noreferrer">ChatGPT Release Notes</a> 的 <strong>Retiring Atlas</strong> 一节重复了同一停止日期。</li></ul><p>今天（2026-08-18）已过官方停止日。浏览代理请用：桌面<strong>内置浏览器</strong>、<a href="https://learn.chatgpt.com/docs/chrome-extension" target="_blank" rel="noreferrer">Chrome 扩展</a>、Work 的 <strong>Cloud Browser</strong>。不要引用 WSJ / Reddit 的合并传闻；上列三篇是唯一口径。</p> 2026-08-09 之后 Atlas 书签 / 密码是否仍能从本机导出，以帮助中心该页的最新修订为准，本教程不写操作步骤。 <h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">学习地图</a> — 全家桶与决策树</li><li><a href="./chatgpt-work.html">ChatGPT Work</a> — 可审成品、插件、Sites</li><li><a href="./codex-cli.html">Codex CLI</a> — 安装与核心功能</li><li><a href="./codex-ai.html">Codex 产品线</a> — CLI、IDE、应用、云端</li><li><a href="./codex-cookbook.html">Codex Cookbook</a> — 任务配方</li><li><a href="./codex-cheatsheet.html">Codex 速查表</a> — 命令和配置键</li></ul><h2 id="官方来源" tabindex="-1">官方来源 <a class="header-anchor" href="#官方来源" aria-label="Permalink to &quot;官方来源&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">Pricing</a> — 套餐和配额的唯一权威</li><li><a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a> — Chat / Work / Codex</li><li><a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">Models</a> — 模型列表和推理强度</li><li><a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Configuration Reference</a> — <code>requirements.toml</code> 和每个配置键</li><li><a href="https://help.openai.com/en/articles/20001371-evolving-atlas-into-chatgpt-for-browser-based-agentic-work" target="_blank" rel="noreferrer">Evolving Atlas</a></li></ul>`,52)])])}const m=e(d,[["render",s]]);export{C as __pageData,m as default};
